package EmployeeManagementSystem.controller;
import EmployeeManagementSystem.service.RequestScopeService;
import EmployeeManagementSystem.entity.*; import EmployeeManagementSystem.security.jwt.JwtUtil; import EmployeeManagementSystem.repository.EmployeeRepository; import EmployeeManagementSystem.service.InternalMobilityService; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/internal-mobility") public class InternalMobilityController{
 private final RequestScopeService scope;
 private final InternalMobilityService service; private final JwtUtil jwt; private final EmployeeRepository employees;
 public InternalMobilityController(InternalMobilityService s,JwtUtil j,EmployeeRepository e,RequestScopeService requestScope){this.scope=requestScope;service=s;jwt=j;employees=e;}
 private String tok(String a){if(a==null||!a.startsWith("Bearer "))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Authentication required.");return a.substring(7);} private String user(String a){return jwt.extractUsername(tok(a));} private String role(String a){String r=jwt.extractRole(tok(a));return r==null?"":r.replace("ROLE_","").toUpperCase();} private boolean mgmt(String r){return Set.of("ADMIN","HR","MANAGER").contains(r);}
 @GetMapping("/postings") public List<InternalJobPosting> postings(@RequestHeader("Authorization")String a){return service.postings(mgmt(role(a)));}
 @PostMapping("/postings") public InternalJobPosting create(@RequestHeader("Authorization")String a,@RequestBody InternalJobPosting x){if(!mgmt(role(a)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Management access required.");String u=user(a),n=employees.findByRegisterEmployee_UserId(u).map(e->e.getFullName()).orElse(u);try{return service.createPosting(x,u,n);}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,e.getMessage());}}
 @PatchMapping("/postings/{id}") public InternalJobPosting update(@RequestHeader("Authorization")String a,@PathVariable Long id,@RequestBody InternalJobPosting x){if(!mgmt(role(a)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Management access required.");try{return service.updatePosting(id,x);}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,e.getMessage());}}
 @PostMapping("/postings/{id}/close") public InternalJobPosting close(@RequestHeader("Authorization")String a,@PathVariable Long id){if(!mgmt(role(a)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Management access required.");try{return service.closePosting(id);}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,e.getMessage());}}
 @GetMapping("/applications/my") public List<InternalJobApplication> my(@RequestHeader("Authorization")String a){return service.myApplications(user(a));}
 @GetMapping("/applications") public List<InternalJobApplication> all(@RequestHeader("Authorization")String a){if(!mgmt(role(a)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Management access required.");return scope.visibleTo(role(a),user(a),service.applications());}
 @PostMapping("/postings/{id}/apply") public InternalJobApplication apply(@RequestHeader("Authorization")String a,@PathVariable Long id,@RequestBody InternalJobApplication x){String u=user(a),n=employees.findByRegisterEmployee_UserId(u).map(e->e.getFullName()).orElse(u);try{return service.apply(id,x,u,n);}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,e.getMessage());}}
 @PatchMapping("/applications/{id}/review") public InternalJobApplication review(@RequestHeader("Authorization")String a,@PathVariable Long id,@RequestBody Map<String,Object>b){scope.assertCanReviewById(role(a),user(a),service.applications(),id);if(!mgmt(role(a)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Management access required.");try{return service.review(id,String.valueOf(b.get("status")),String.valueOf(b.getOrDefault("comment","")),user(a));}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,e.getMessage());}}
}
